update licoes set titulo = 'Saudações e apresentações II', exemplos = $j$[{"en":"Hello, my name is Ana.","pt":"Olá, meu nome é Ana."},{"en":"Nice to meet you.","pt":"Prazer em conhecê-lo."},{"en":"Good morning, everyone.","pt":"Bom dia, pessoal."},{"en":"How are you today?","pt":"Como você está hoje?"},{"en":"See you later!","pt":"Até mais tarde!"}]$j$::jsonb, questoes = $j$[{"q":"'_____, my name is John.'","ans":0,"ctx":"Cumprimento","exp":"'Hello' é a saudação mais comum para se apresentar.","opts":["Hello","Goodbye","Thanks","Sorry"]},{"q":"'Nice to _____ you.'","ans":0,"ctx":"Ao conhecer alguém","exp":"'Nice to meet you' = prazer em conhecê-lo.","opts":["meet","eat","see","read"]},{"q":"'Good _____, everyone!' (de manhã)","ans":0,"ctx":"Período da manhã","exp":"'Good morning' é usado de manhã.","opts":["morning","night","afternoon","evening"]},{"q":"'How _____ you today?'","ans":0,"ctx":"","exp":"'How are you?' = como você está?","opts":["are","is","am","be"]},{"q":"'_____ you later!' (despedida)","ans":0,"ctx":"Ao se despedir","exp":"'See you later' = até mais tarde.","opts":["See","Look","Watch","Find"]}]$j$::jsonb where id = '0f98d375-8175-4972-a83f-658f0c4825b7';
update licoes set titulo = 'Pronomes pessoais II', exemplos = $j$[{"en":"I am a student.","pt":"Eu sou estudante."},{"en":"You are my friend.","pt":"Você é meu amigo."},{"en":"He is tall.","pt":"Ele é alto."},{"en":"She is happy.","pt":"Ela está feliz."},{"en":"They are at home.","pt":"Eles estão em casa."}]$j$::jsonb, questoes = $j$[{"q":"'_____ am a teacher.'","ans":0,"ctx":"eu","exp":"'I am' = eu sou.","opts":["I","You","He","She"]},{"q":"'_____ is my brother.' (homem)","ans":0,"ctx":"ele","exp":"'He' é usado para homem.","opts":["He","She","They","It"]},{"q":"'_____ is my sister.' (mulher)","ans":0,"ctx":"ela","exp":"'She' é usado para mulher.","opts":["She","He","It","We"]},{"q":"'_____ are students.' (eles)","ans":0,"ctx":"plural","exp":"'They' = eles/elas.","opts":["They","He","She","It"]},{"q":"'_____ are my friend.' (você)","ans":0,"ctx":"você","exp":"'You are' = você é.","opts":["You","I","He","She"]}]$j$::jsonb where id = 'bfcf44e1-7648-4617-ad31-879680adde9a';
update licoes set titulo = 'Plural dos substantivos III', exemplos = $j$[{"en":"One cat, two cats.","pt":"Um gato, dois gatos."},{"en":"I have three boxes.","pt":"Tenho três caixas."},{"en":"The babies are sleeping.","pt":"Os bebês estão dormindo."},{"en":"We need more dishes.","pt":"Precisamos de mais pratos."},{"en":"Those men are tall.","pt":"Aqueles homens são altos."}]$j$::jsonb, questoes = $j$[{"q":"One book, two _____.","ans":0,"ctx":"","exp":"Plural simples: book → books.","opts":["books","bookes","bookies","book"]},{"q":"The plural of 'box' is _____.","ans":0,"ctx":"","exp":"Termina em -x, ganha -es: boxes.","opts":["boxes","boxs","box","boxies"]},{"q":"The plural of 'baby' is _____.","ans":0,"ctx":"","exp":"Consoante + y vira -ies: babies.","opts":["babies","babys","babyes","baby"]},{"q":"The plural of 'man' is _____.","ans":0,"ctx":"","exp":"Irregular: man → men.","opts":["men","mans","mens","man"]},{"q":"The plural of 'child' is _____.","ans":0,"ctx":"","exp":"Irregular: child → children.","opts":["children","childs","childer","child"]}]$j$::jsonb where id = '3f11f444-9047-43d6-bf6f-ab4691031570';
update licoes set titulo = 'Partes do corpo II', exemplos = $j$[{"en":"I have two eyes.","pt":"Tenho dois olhos."},{"en":"My head hurts.","pt":"Minha cabeça dói."},{"en":"She has small hands.","pt":"Ela tem mãos pequenas."},{"en":"Open your mouth.","pt":"Abra sua boca."},{"en":"He broke his leg.","pt":"Ele quebrou a perna."}]$j$::jsonb, questoes = $j$[{"q":"You see with your _____.","ans":0,"ctx":"","exp":"Vemos com os olhos (eyes).","opts":["eyes","ears","nose","hands"]},{"q":"You hear with your _____.","ans":0,"ctx":"","exp":"Ouvimos com os ouvidos (ears).","opts":["ears","eyes","mouth","feet"]},{"q":"You smell with your _____.","ans":0,"ctx":"","exp":"Cheiramos com o nariz (nose).","opts":["nose","eyes","ears","hands"]},{"q":"You walk with your _____.","ans":0,"ctx":"","exp":"Andamos com as pernas (legs).","opts":["legs","arms","eyes","ears"]},{"q":"You hold things with your _____.","ans":0,"ctx":"","exp":"Seguramos coisas com as mãos (hands).","opts":["hands","feet","nose","ears"]}]$j$::jsonb where id = '343d2938-ef04-4c9a-a943-bba1ee83da13';
update licoes set titulo = 'Profissões II', exemplos = $j$[{"en":"She is a doctor.","pt":"Ela é médica."},{"en":"He works as a teacher.","pt":"Ele trabalha como professor."},{"en":"The cook makes great food.","pt":"O cozinheiro faz comida ótima."},{"en":"My father is a driver.","pt":"Meu pai é motorista."},{"en":"A nurse helps sick people.","pt":"Um enfermeiro ajuda pessoas doentes."}]$j$::jsonb, questoes = $j$[{"q":"A _____ teaches students.","ans":0,"ctx":"","exp":"O professor (teacher) ensina.","opts":["teacher","doctor","driver","cook"]},{"q":"A _____ helps sick people in a hospital.","ans":0,"ctx":"","exp":"O médico (doctor) ajuda os doentes.","opts":["doctor","teacher","farmer","pilot"]},{"q":"A _____ cooks food in a restaurant.","ans":0,"ctx":"","exp":"O cozinheiro (cook) prepara a comida.","opts":["cook","driver","nurse","singer"]},{"q":"A _____ flies a plane.","ans":0,"ctx":"","exp":"O piloto (pilot) voa o avião.","opts":["pilot","doctor","teacher","farmer"]},{"q":"A _____ grows food on a farm.","ans":0,"ctx":"","exp":"O fazendeiro (farmer) cultiva na fazenda.","opts":["farmer","cook","pilot","nurse"]}]$j$::jsonb where id = 'e1d9f10e-f3a9-4802-8578-996ba6050687';
update licoes set titulo = 'Preposições de lugar II', exemplos = $j$[{"en":"The cat is on the table.","pt":"O gato está na mesa."},{"en":"The ball is under the chair.","pt":"A bola está embaixo da cadeira."},{"en":"The keys are in the bag.","pt":"As chaves estão na bolsa."},{"en":"She sits next to me.","pt":"Ela senta ao meu lado."},{"en":"The shop is behind the bank.","pt":"A loja fica atrás do banco."}]$j$::jsonb, questoes = $j$[{"q":"The book is _____ the table. (em cima)","ans":0,"ctx":"","exp":"'On' = em cima.","opts":["on","under","in","behind"]},{"q":"The cat is _____ the box. (dentro)","ans":0,"ctx":"","exp":"'In' = dentro.","opts":["in","on","under","next"]},{"q":"The ball is _____ the bed. (embaixo)","ans":0,"ctx":"","exp":"'Under' = embaixo.","opts":["under","on","in","behind"]},{"q":"The car is _____ the house. (atrás)","ans":0,"ctx":"","exp":"'Behind' = atrás.","opts":["behind","on","in","under"]},{"q":"She sits _____ to her friend. (ao lado)","ans":0,"ctx":"","exp":"'Next to' = ao lado.","opts":["next","on","under","in"]}]$j$::jsonb where id = '5a176b86-c99e-468e-a40d-d1f7028e43fb';
update licoes set titulo = 'There is / There are III', exemplos = $j$[{"en":"There is a book on the table.","pt":"Há um livro na mesa."},{"en":"There are three cats in the garden.","pt":"Há três gatos no jardim."},{"en":"Is there a bank near here?","pt":"Há um banco perto daqui?"},{"en":"There are many people here.","pt":"Há muitas pessoas aqui."},{"en":"There is no milk in the fridge.","pt":"Não há leite na geladeira."}]$j$::jsonb, questoes = $j$[{"q":"'_____ a cat on the bed.' (singular)","ans":0,"ctx":"","exp":"Singular usa 'There is'.","opts":["There is","There are","There be","It is"]},{"q":"'_____ five apples here.' (plural)","ans":0,"ctx":"","exp":"Plural usa 'There are'.","opts":["There are","There is","There be","It are"]},{"q":"'_____ there a hospital near here?'","ans":0,"ctx":"","exp":"Pergunta no singular: Is there...?","opts":["Is","Are","Be","Am"]},{"q":"'There _____ many cars in the street.'","ans":0,"ctx":"","exp":"Plural (cars) usa 'are'.","opts":["are","is","am","be"]},{"q":"'There _____ a problem with my phone.'","ans":0,"ctx":"","exp":"Singular usa 'is'.","opts":["is","are","am","be"]}]$j$::jsonb where id = '8bd5c8a5-87d1-4e9f-9c77-05abf5ca72cc';
update licoes set titulo = 'Imperativo II', exemplos = $j$[{"en":"Open the door, please.","pt":"Abra a porta, por favor."},{"en":"Don't run in the hall.","pt":"Não corra no corredor."},{"en":"Sit down.","pt":"Sente-se."},{"en":"Please be quiet.","pt":"Por favor, fique quieto."},{"en":"Don't forget your keys.","pt":"Não esqueça suas chaves."}]$j$::jsonb, questoes = $j$[{"q":"'_____ the window, please.' (abra)","ans":0,"ctx":"","exp":"Imperativo: verbo no início.","opts":["Open","Opens","Opening","To open"]},{"q":"'_____ down, please.' (sente)","ans":0,"ctx":"","exp":"Imperativo: Sit.","opts":["Sit","Sits","Sitting","To sit"]},{"q":"'_____ run here!' (não corra)","ans":0,"ctx":"","exp":"Negativo: Don't.","opts":["Don't","Doesn't","Not","No"]},{"q":"'Please _____ quiet.' (fique)","ans":0,"ctx":"","exp":"Imperativo de be: Be.","opts":["be","is","are","being"]},{"q":"'_____ forget your bag!' (não esqueça)","ans":0,"ctx":"","exp":"Negativo: Don't.","opts":["Don't","Doesn't","Not","No"]}]$j$::jsonb where id = '3ec6d7e0-0978-4aa5-879f-95a43d5e29e0';
update licoes set titulo = 'A casa e os cômodos II', exemplos = $j$[{"en":"The kitchen is small.","pt":"A cozinha é pequena."},{"en":"I sleep in my bedroom.","pt":"Durmo no meu quarto."},{"en":"We watch TV in the living room.","pt":"Assistimos TV na sala."},{"en":"The bathroom is upstairs.","pt":"O banheiro fica em cima."},{"en":"There is a garden behind the house.","pt":"Há um jardim atrás da casa."}]$j$::jsonb, questoes = $j$[{"q":"'We cook food in the _____.'","ans":0,"ctx":"","exp":"kitchen = cozinha.","opts":["kitchen","bedroom","bathroom","garage"]},{"q":"'We sleep in the _____.'","ans":0,"ctx":"","exp":"bedroom = quarto.","opts":["bedroom","kitchen","garden","garage"]},{"q":"'We take a shower in the _____.'","ans":0,"ctx":"","exp":"bathroom = banheiro.","opts":["bathroom","kitchen","bedroom","living room"]},{"q":"'We watch TV in the _____.'","ans":0,"ctx":"","exp":"living room = sala.","opts":["living room","bathroom","garage","garden"]},{"q":"'We park the car in the _____.'","ans":0,"ctx":"","exp":"garage = garagem.","opts":["garage","bedroom","kitchen","bathroom"]}]$j$::jsonb where id = '437a2af3-8b4b-40f8-a870-1a3d60d8b66c';
update licoes set titulo = 'Compras e dinheiro II', exemplos = $j$[{"en":"How much is this shirt?","pt":"Quanto custa esta camisa?"},{"en":"It costs ten dollars.","pt":"Custa dez dólares."},{"en":"I want to buy some bread.","pt":"Quero comprar um pão."},{"en":"Can I pay by card?","pt":"Posso pagar com cartão?"},{"en":"That's too expensive.","pt":"Isso é caro demais."}]$j$::jsonb, questoes = $j$[{"q":"'_____ much is this?' (quanto custa)","ans":0,"ctx":"","exp":"'How much' pergunta preço.","opts":["How","What","Where","Who"]},{"q":"'It _____ five dollars.' (custa)","ans":0,"ctx":"","exp":"'costs' (it ganha -s).","opts":["costs","cost","costing","is cost"]},{"q":"'I want to _____ a new phone.' (comprar)","ans":0,"ctx":"","exp":"buy = comprar.","opts":["buy","sell","pay","cost"]},{"q":"'Can I _____ by card?' (pagar)","ans":0,"ctx":"","exp":"pay = pagar.","opts":["pay","buy","sell","cost"]},{"q":"'This is very _____. It's not cheap.' (caro)","ans":0,"ctx":"","exp":"expensive = caro.","opts":["expensive","cheap","free","small"]}]$j$::jsonb where id = '7b9f1dc7-4741-4578-b085-4d607063c228';
update licoes set titulo = 'No restaurante II', exemplos = $j$[{"en":"A table for two, please.","pt":"Uma mesa para dois, por favor."},{"en":"Can I see the menu?","pt":"Posso ver o cardápio?"},{"en":"I would like a salad.","pt":"Eu gostaria de uma salada."},{"en":"The bill, please.","pt":"A conta, por favor."},{"en":"The food is delicious.","pt":"A comida está deliciosa."}]$j$::jsonb, questoes = $j$[{"q":"'Can I see the _____, please?' (cardápio)","ans":0,"ctx":"","exp":"menu = cardápio.","opts":["menu","bill","table","waiter"]},{"q":"'A _____ for two, please.' (mesa)","ans":0,"ctx":"","exp":"table = mesa.","opts":["table","menu","bill","chair"]},{"q":"'I would _____ a coffee.' (gostaria)","ans":0,"ctx":"","exp":"'would like' = gostaria.","opts":["like","want","need","have"]},{"q":"'The _____, please.' (a conta)","ans":0,"ctx":"","exp":"bill = conta.","opts":["bill","menu","table","food"]},{"q":"'The _____ brings the food.' (garçom)","ans":0,"ctx":"","exp":"waiter = garçom.","opts":["waiter","cook","menu","bill"]}]$j$::jsonb where id = '3be635dd-433a-48a4-a9cf-65c2c201b1a9';
update licoes set titulo = 'Pronomes possessivos II', exemplos = $j$[{"en":"This book is mine.","pt":"Este livro é meu."},{"en":"Is this pen yours?","pt":"Esta caneta é sua?"},{"en":"The red car is hers.","pt":"O carro vermelho é dela."},{"en":"That house is theirs.","pt":"Aquela casa é deles."},{"en":"These seats are ours.","pt":"Estes assentos são nossos."}]$j$::jsonb, questoes = $j$[{"q":"'This bag is _____.' (meu)","ans":0,"ctx":"","exp":"meu (pronome) = mine.","opts":["mine","my","me","mines"]},{"q":"'Is this book _____?' (seu)","ans":0,"ctx":"","exp":"seu (pronome) = yours.","opts":["yours","your","you","you's"]},{"q":"'The car is _____.' (dela)","ans":0,"ctx":"","exp":"dela (pronome) = hers.","opts":["hers","her","she","her's"]},{"q":"'That house is _____.' (deles)","ans":0,"ctx":"","exp":"deles (pronome) = theirs.","opts":["theirs","their","them","there's"]},{"q":"'These tickets are _____.' (nossos)","ans":0,"ctx":"","exp":"nossos (pronome) = ours.","opts":["ours","our","us","our's"]}]$j$::jsonb where id = '8530ce35-32f0-45f6-951a-b5248eb98262';
update licoes set titulo = 'Pronomes relativos II', exemplos = $j$[{"en":"The man who called is my uncle.","pt":"O homem que ligou é meu tio."},{"en":"The book which I read was good.","pt":"O livro que li era bom."},{"en":"This is the house that I love.","pt":"Esta é a casa que eu amo."},{"en":"She is the woman who helped me.","pt":"Ela é a mulher que me ajudou."},{"en":"The car which broke down is old.","pt":"O carro que quebrou é velho."}]$j$::jsonb, questoes = $j$[{"q":"'The man _____ called is my friend.' (pessoa)","ans":0,"ctx":"","exp":"who = pessoas.","opts":["who","which","where","what"]},{"q":"'The book _____ I read was great.' (coisa)","ans":0,"ctx":"","exp":"which = coisas.","opts":["which","who","where","what"]},{"q":"'She is the teacher _____ helped me.' (pessoa)","ans":0,"ctx":"","exp":"who = pessoas.","opts":["who","which","where","what"]},{"q":"'Which is used for _____.'","ans":0,"ctx":"","exp":"which = coisas.","opts":["things","people","places","time"]},{"q":"'_____ can be used for both people and things.'","ans":0,"ctx":"","exp":"that = ambos.","opts":["That","Who","Which","Where"]}]$j$::jsonb where id = '2e37f599-ccb3-48d3-964a-394b19a7e95d';
update licoes set titulo = 'Question Tags II', exemplos = $j$[{"en":"You are tired, aren't you?","pt":"Você está cansado, não está?"},{"en":"She likes coffee, doesn't she?","pt":"Ela gosta de café, não gosta?"},{"en":"They aren't ready, are they?","pt":"Eles não estão prontos, estão?"},{"en":"He can swim, can't he?","pt":"Ele sabe nadar, não sabe?"},{"en":"It's cold, isn't it?","pt":"Está frio, não está?"}]$j$::jsonb, questoes = $j$[{"q":"'You are happy, _____?' (não está)","ans":0,"ctx":"","exp":"Afirmativa → tag negativa.","opts":["aren't you","are you","do you","isn't it"]},{"q":"'She likes tea, _____?' (não gosta)","ans":0,"ctx":"","exp":"likes → doesn't she.","opts":["doesn't she","does she","isn't she","don't she"]},{"q":"'They aren't here, _____?' (estão)","ans":0,"ctx":"","exp":"Negativa → tag afirmativa.","opts":["are they","aren't they","do they","is they"]},{"q":"'He can drive, _____?' (não sabe)","ans":0,"ctx":"","exp":"can → can't he.","opts":["can't he","can he","does he","doesn't he"]},{"q":"'An affirmative sentence takes a _____ tag.'","ans":0,"ctx":"","exp":"tag negativa.","opts":["negative","affirmative","future","past"]}]$j$::jsonb where id = '5e5c894f-2d16-47bd-aa17-453797b10cbc';
update licoes set titulo = 'Gerúndio ou Infinitivo? II', exemplos = $j$[{"en":"I enjoy reading books.","pt":"Gosto de ler livros."},{"en":"She wants to travel.","pt":"Ela quer viajar."},{"en":"He finished working at six.","pt":"Ele terminou de trabalhar às seis."}]$j$::jsonb, questoes = $j$[{"q":"'I enjoy ___.'","ans":0,"ctx":"nadar","exp":"enjoy + ing.","opts":["swimming","to swim","swim","swims"]},{"q":"'She wants ___ home.'","ans":0,"ctx":"ir","exp":"want + to.","opts":["to go","going","go","goes"]},{"q":"'They avoid ___ late.'","ans":0,"ctx":"","exp":"avoid + ing.","opts":["arriving","to arrive","arrive","arrived"]},{"q":"'We decided ___ a car.'","ans":0,"ctx":"","exp":"decide + to.","opts":["to buy","buying","buy","bought"]},{"q":"'He finished ___ the report.'","ans":0,"ctx":"","exp":"finish + ing.","opts":["writing","to write","write","wrote"]},{"q":"'I hope ___ you soon.'","ans":0,"ctx":"","exp":"hope + to.","opts":["to see","seeing","see","saw"]}]$j$::jsonb where id = '72a76778-76cd-499f-adeb-217e14830a8d';
update licoes set titulo = 'Will vs Going to II', exemplos = $j$[{"en":"I'm going to visit Italy next year.","pt":"Vou visitar a Itália ano que vem. (plano)"},{"en":"That bag looks heavy. I'll help you.","pt":"Essa bolsa parece pesada. Vou te ajudar. (decisão)"},{"en":"Look! It's going to rain.","pt":"Olha! Vai chover. (evidência)"}]$j$::jsonb, questoes = $j$[{"q":"Plano já decidido usa:","ans":0,"ctx":"","exp":"Plano: going to.","opts":["going to","will","do","-ing"]},{"q":"Decisão na hora usa:","ans":0,"ctx":"","exp":"Decisão imediata: will.","opts":["will","going to","do","-ing"]},{"q":"'The phone is ringing. I ___ answer it.'","ans":0,"ctx":"","exp":"Decisão na hora: will.","opts":["will","am going to","going to","do"]},{"q":"'We ___ get married in June.'","ans":0,"ctx":"plano","exp":"Plano: are going to.","opts":["are going to","will","do","going"]},{"q":"'Look at those clouds! It ___ rain.'","ans":0,"ctx":"evidência","exp":"Evidência: is going to.","opts":["is going to","will","does","go to"]},{"q":"Os dois (will e going to) falam de:","ans":0,"ctx":"","exp":"Ambos = futuro.","opts":["Futuro","Passado","Presente","Rotina"]}]$j$::jsonb where id = 'dbc2594c-2f52-40de-9592-3ab36b245081';
update licoes set titulo = 'Too / enough II', exemplos = $j$[{"en":"This coffee is too hot.","pt":"Este café está quente demais."},{"en":"She is old enough to drive.","pt":"Ela tem idade suficiente para dirigir."},{"en":"I don't have enough time.","pt":"Não tenho tempo suficiente."}]$j$::jsonb, questoes = $j$[{"q":"'It's ___ expensive.' (caro demais)","ans":0,"ctx":"","exp":"too = demais.","opts":["too","enough","very too","so enough"]},{"q":"'He's tall ___.' (alto o suficiente)","ans":0,"ctx":"","exp":"enough vem depois do adjetivo.","opts":["enough","too","so","very"]},{"q":"'I don't have ___ money.'","ans":0,"ctx":"suficiente","exp":"enough money.","opts":["enough","too","so","much too"]},{"q":"'too' vem ___ do adjetivo:","ans":0,"ctx":"","exp":"too + adjetivo.","opts":["antes","depois","no lugar","nunca perto"]},{"q":"'This box is ___ heavy to carry.'","ans":0,"ctx":"","exp":"too heavy.","opts":["too","enough","so enough","very enough"]},{"q":"'Are you warm ___?'","ans":0,"ctx":"o suficiente","exp":"warm enough.","opts":["enough","too","so","very"]}]$j$::jsonb where id = '0ef7a716-7aae-41a2-97c2-b417d1322c74';
update licoes set titulo = 'Advérbios de modo II', exemplos = $j$[{"en":"He drives carefully.","pt":"Ele dirige com cuidado."},{"en":"She speaks English well.","pt":"Ela fala inglês bem."},{"en":"Please walk slowly.","pt":"Por favor, ande devagar."}]$j$::jsonb, questoes = $j$[{"q":"Advérbio de 'quick':","ans":0,"ctx":"","exp":"quick → quickly.","opts":["quickly","quick","quicker","quickness"]},{"q":"Advérbio de 'good':","ans":0,"ctx":"","exp":"good → well (irregular).","opts":["well","goodly","gooder","best"]},{"q":"'She sings ___.' (lindamente)","ans":0,"ctx":"","exp":"beautiful → beautifully.","opts":["beautifully","beautiful","beauty","beautifuly"]},{"q":"Advérbios de modo dizem:","ans":0,"ctx":"","exp":"Modo = como.","opts":["Como algo é feito","Quando","Onde","Quanto"]},{"q":"'He works ___.' (com afinco)","ans":0,"ctx":"","exp":"'hard' é igual (hardly = quase não).","opts":["hard","hardly","harder","hardness"]},{"q":"Advérbio de 'careful':","ans":0,"ctx":"","exp":"careful → carefully.","opts":["carefully","carefuly","careful","carefulness"]}]$j$::jsonb where id = '30ec9703-e7e7-4aad-b103-3452f326b286';
update licoes set titulo = 'Contáveis e incontáveis II', exemplos = $j$[{"en":"I have two apples.","pt":"Tenho duas maçãs. (contável)"},{"en":"There is some water.","pt":"Há um pouco de água. (incontável)"},{"en":"How much rice do you want?","pt":"Quanto arroz você quer?"}]$j$::jsonb, questoes = $j$[{"q":"Qual é incontável?","ans":0,"ctx":"","exp":"water = incontável.","opts":["water","apple","book","car"]},{"q":"Qual é contável?","ans":0,"ctx":"","exp":"chair = contável.","opts":["chair","milk","sugar","information"]},{"q":"Incontáveis usam:","ans":0,"ctx":"","exp":"Incontável: much.","opts":["much","many","a few","number"]},{"q":"'I need ___ information.'","ans":0,"ctx":"","exp":"information é incontável: some.","opts":["some","a","an","two"]},{"q":"Qual NÃO tem plural?","ans":0,"ctx":"","exp":"money é incontável.","opts":["money","dog","table","idea"]},{"q":"'How ___ books?' (contável)","ans":0,"ctx":"","exp":"Contável: many.","opts":["many","much","a little","amount of"]}]$j$::jsonb where id = 'c0373df3-bbdc-459e-bb61-6035f8cfd77b';
update licoes set titulo = 'Meio ambiente e sustentabilidade II', exemplos = $j$[{"en":"We should recycle more.","pt":"Deveríamos reciclar mais."},{"en":"Pollution is a big problem.","pt":"A poluição é um grande problema."},{"en":"Climate change affects everyone.","pt":"A mudança climática afeta a todos."}]$j$::jsonb, questoes = $j$[{"q":"'Pollution' significa:","ans":0,"ctx":"","exp":"Pollution = poluição.","opts":["Poluição","Reciclagem","Energia","Floresta"]},{"q":"'Recycle' significa:","ans":0,"ctx":"","exp":"Recycle = reciclar.","opts":["Reciclar","Poluir","Desperdiçar","Queimar"]},{"q":"'Climate change' é:","ans":0,"ctx":"","exp":"Mudança climática.","opts":["Mudança climática","Previsão do tempo","Estação","Temperatura"]},{"q":"'Waste' (verbo) significa:","ans":0,"ctx":"","exp":"Waste = desperdiçar/lixo.","opts":["Desperdiçar","Reciclar","Plantar","Limpar"]},{"q":"'Renewable energy' é:","ans":0,"ctx":"","exp":"Renovável.","opts":["Energia renovável","Energia cara","Energia nuclear","Energia fóssil"]},{"q":"Os 3 R's do meio ambiente:","ans":0,"ctx":"","exp":"Reduce, reuse, recycle.","opts":["Reduce, reuse, recycle","Run, rest, relax","Read, write, repeat","Só recycle"]}]$j$::jsonb where id = '8332eb5e-c32d-4750-9df8-58f32c581f31';
update licoes set titulo = 'Present Perfect Continuous II', exemplos = $j$[{"en":"I have been working since this morning.","pt":"Estou trabalhando desde de manhã."},{"en":"She has been studying English for years.","pt":"Ela estuda inglês há anos."},{"en":"They have been waiting for an hour.","pt":"Eles estão esperando há uma hora."},{"en":"It has been raining all day.","pt":"Está chovendo o dia todo."},{"en":"We have been living here since 2020.","pt":"Moramos aqui desde 2020."}]$j$::jsonb, questoes = $j$[{"q":"'I have _____ working all morning.' (been)","ans":0,"ctx":"","exp":"have been + ing.","opts":["been","being","be","was"]},{"q":"'She has been _____ for hours.' (study)","ans":0,"ctx":"","exp":"been + studying.","opts":["studying","studied","study","studies"]},{"q":"'They _____ been waiting since noon.' (have)","ans":0,"ctx":"","exp":"they: have.","opts":["have","has","had","having"]},{"q":"'Present perfect continuous: have/has been + verb _____.'","ans":0,"ctx":"","exp":"verbo com -ing.","opts":["-ing","-ed","base","to"]},{"q":"'It focuses on the _____ of an action.'","ans":0,"ctx":"","exp":"foco na duração.","opts":["duration","end","beginning","place"]}]$j$::jsonb where id = '4f6bd7fa-da31-4440-a092-ad3589f83212';
update licoes set titulo = 'Second Conditional II', exemplos = $j$[{"en":"If I had more money, I would travel the world.","pt":"Se eu tivesse mais dinheiro, viajaria o mundo."},{"en":"If she studied harder, she would pass.","pt":"Se ela estudasse mais, passaria."},{"en":"What would you do if you won the lottery?","pt":"O que você faria se ganhasse na loteria?"},{"en":"If I were you, I would accept the offer.","pt":"Se eu fosse você, aceitaria a oferta."},{"en":"We would help if we could.","pt":"Ajudaríamos se pudéssemos."}]$j$::jsonb, questoes = $j$[{"q":"'If I _____ rich, I would buy a house.' (fosse - be)","ans":0,"ctx":"","exp":"No 2nd conditional usa-se 'were'.","opts":["were","am","was","will be"]},{"q":"'If she studied, she _____ pass.' (passaria)","ans":0,"ctx":"","exp":"would no resultado.","opts":["would","will","did","was"]},{"q":"'If I _____ more time, I would help.' (tivesse - have)","ans":0,"ctx":"","exp":"If + passado.","opts":["had","have","will have","would have"]},{"q":"'Second conditional: If + past, _____ + verb.'","ans":0,"ctx":"","exp":"would no resultado.","opts":["would","will","had","was"]},{"q":"'Second conditional describes _____ situations.'","ans":0,"ctx":"","exp":"imaginárias.","opts":["imaginary","real","factual","past"]}]$j$::jsonb where id = '5d613be8-22ed-41de-8821-eead2077ce49';
update licoes set titulo = 'Third Conditional II', exemplos = $j$[{"en":"If I had studied, I would have passed the exam.","pt":"Se eu tivesse estudado, teria passado na prova."},{"en":"She would have come if you had invited her.","pt":"Ela teria vindo se você a tivesse convidado."},{"en":"If we had left earlier, we wouldn't have missed the train.","pt":"Se tivéssemos saído mais cedo, não teríamos perdido o trem."},{"en":"They would have won if they had played better.","pt":"Eles teriam ganhado se tivessem jogado melhor."},{"en":"If he had known, he would have helped.","pt":"Se ele soubesse, teria ajudado."}]$j$::jsonb, questoes = $j$[{"q":"'If I _____ studied, I would have passed.' (tivesse - had)","ans":0,"ctx":"","exp":"If + had + particípio.","opts":["had","have","would","was"]},{"q":"'She would _____ come if you had asked.' (teria)","ans":0,"ctx":"","exp":"would have + particípio.","opts":["have","has","had","be"]},{"q":"'If we had left earlier, we _____ have missed it.' (negativo)","ans":0,"ctx":"","exp":"wouldn't have.","opts":["wouldn't","won't","didn't","hadn't"]},{"q":"'Third conditional: If + had + participle, would _____ + participle.'","ans":0,"ctx":"","exp":"would have.","opts":["have","has","had","be"]},{"q":"'Third conditional describes _____ situations.'","ans":0,"ctx":"","exp":"passado irreal.","opts":["unreal past","real future","present facts","habits"]}]$j$::jsonb where id = 'a7ce4d35-ceea-4a14-bda9-6407e4f5d55b';
update licoes set titulo = 'Orações relativas II', exemplos = $j$[{"en":"The book that I bought is great.","pt":"O livro que comprei é ótimo."},{"en":"My sister, who is a doctor, lives in Rio.","pt":"Minha irmã, que é médica, mora no Rio."},{"en":"The house where I grew up is gone.","pt":"A casa onde cresci não existe mais."},{"en":"Paris, which is in France, is beautiful.","pt":"Paris, que fica na França, é linda."},{"en":"The woman whose car broke down called for help.","pt":"A mulher cujo carro quebrou pediu ajuda."}]$j$::jsonb, questoes = $j$[{"q":"'Non-defining clauses are separated by _____.'","ans":0,"ctx":"","exp":"vírgulas.","opts":["commas","dashes","nothing","that"]},{"q":"'The book _____ I bought is great.' (que - coisa)","ans":0,"ctx":"","exp":"that para coisas.","opts":["that","who","where","whose"]},{"q":"'My sister, _____ is a doctor, lives in Rio.' (pessoa)","ans":0,"ctx":"","exp":"who para pessoas.","opts":["who","which","that","where"]},{"q":"'Non-defining clauses give _____ information.'","ans":0,"ctx":"","exp":"informação extra.","opts":["extra","essential","false","no"]},{"q":"'Which word is NOT used in non-defining clauses?'","ans":0,"ctx":"","exp":"'that' não é usado.","opts":["that","who","which","whose"]}]$j$::jsonb where id = 'a3653bae-c40f-43b3-93f5-f921bb8b45b8';
update licoes set titulo = 'Question tags III', exemplos = $j$[{"en":"You're coming, aren't you?","pt":"Você vem, né?"},{"en":"She doesn't like fish, does she?","pt":"Ela não gosta de peixe, gosta?"},{"en":"Let's start, shall we?","pt":"Vamos começar, que tal?"}]$j$::jsonb, questoes = $j$[{"q":"'You're tired, ___?'","ans":0,"ctx":"","exp":"Positiva → negativa.","opts":["aren't you","are you","isn't it","don't you"]},{"q":"'He can't swim, ___?'","ans":0,"ctx":"","exp":"Negativa → positiva.","opts":["can he","can't he","does he","is he"]},{"q":"'I'm late, ___?' (exceção):","ans":0,"ctx":"","exp":"Aren't I é a forma aceita.","opts":["aren't I","amn't I","am I","isn't I"]},{"q":"'Let's go, ___?'","ans":0,"ctx":"","exp":"Let's → shall we.","opts":["shall we","will we","do we","let we"]},{"q":"'She went home, ___?'","ans":0,"ctx":"","exp":"Past simple → didn't.","opts":["didn't she","doesn't she","hasn't she","wasn't she"]},{"q":"'They've finished, ___?'","ans":0,"ctx":"","exp":"Have → haven't.","opts":["haven't they","didn't they","aren't they","don't they"]}]$j$::jsonb where id = 'e3aac3cc-8a2a-4f14-b11f-52bb9924f036';
update licoes set titulo = 'Adjetivo + preposição II', exemplos = $j$[{"en":"She's really good at math.","pt":"Ela é muito boa em matemática."},{"en":"I'm interested in photography.","pt":"Tenho interesse em fotografia."},{"en":"He's afraid of spiders.","pt":"Ele tem medo de aranha."}]$j$::jsonb, questoes = $j$[{"q":"'Bom em inglês':","ans":0,"ctx":"","exp":"Good AT.","opts":["good at English","good in English","good on English","good with English only"]},{"q":"'Com medo de altura':","ans":0,"ctx":"","exp":"Afraid OF.","opts":["afraid of heights","afraid from heights","afraid with heights","afraid at heights"]},{"q":"'Interessado em arte':","ans":0,"ctx":"","exp":"Interested IN.","opts":["interested in art","interested on art","interested at art","interested for art"]},{"q":"'Orgulhoso de você':","ans":0,"ctx":"","exp":"Proud OF.","opts":["proud of you","proud with you","proud for you","proud at you"]},{"q":"'Responsável pelo projeto':","ans":0,"ctx":"","exp":"Responsible FOR.","opts":["responsible for the project","responsible of the project","responsible by the project","responsible at it"]},{"q":"'Parecido com o pai':","ans":0,"ctx":"","exp":"Similar TO.","opts":["similar to his father","similar with his father","similar of his father","similar as his father"]}]$j$::jsonb where id = 'd57d8d62-3d46-4dbd-94b3-db34b8cf2250';
update licoes set titulo = 'Phrasal verbs com GET II', exemplos = $j$[{"en":"I get up at 6 every day.","pt":"Levanto às 6 todo dia."},{"en":"Do you get along with your boss?","pt":"Você se dá bem com seu chefe?"},{"en":"Let's get together this weekend!","pt":"Vamos nos reunir este fim de semana!"}]$j$::jsonb, questoes = $j$[{"q":"'Levantar da cama':","ans":0,"ctx":"","exp":"Get up at 7.","opts":["get up","get off","get out only","get on"]},{"q":"'Dar-se bem com':","ans":0,"ctx":"","exp":"Get along.","opts":["get along with","get up with","get over with","get back with"]},{"q":"'Embarcar no ônibus':","ans":0,"ctx":"","exp":"On = transportes grandes.","opts":["get on the bus","get in the bus","get up the bus","get at the bus"]},{"q":"'Entrar no carro':","ans":0,"ctx":"","exp":"In = carro/táxi.","opts":["get in the car","get on the car","get up the car","get to car"]},{"q":"'Voltar (de viagem)':","ans":0,"ctx":"","exp":"When do you get back?","opts":["get back","get again","get return","get behind"]},{"q":"'Reunir-se':","ans":0,"ctx":"","exp":"Get together.","opts":["get together","get union","get meet","get group"]}]$j$::jsonb where id = '1d1a28a4-1cad-4abf-a6c6-e8fe5dba06d9';
update licoes set titulo = 'Phrasal verbs com PUT II', exemplos = $j$[{"en":"Put on your jacket — it's cold.","pt":"Vista a jaqueta — está frio."},{"en":"They put off the meeting again.","pt":"Adiaram a reunião de novo."},{"en":"I won't put up with this behavior.","pt":"Não vou tolerar esse comportamento."}]$j$::jsonb, questoes = $j$[{"q":"'Vestir':","ans":0,"ctx":"","exp":"Put on your shoes.","opts":["put on","put off","put in","put away"]},{"q":"'Adiar':","ans":0,"ctx":"","exp":"Put off = postpone.","opts":["put off","put on","put out","put down"]},{"q":"'Aguentar/tolerar':","ans":0,"ctx":"","exp":"3 partes!","opts":["put up with","put on with","put off with","put over with"]},{"q":"'Guardar (no lugar)':","ans":0,"ctx":"","exp":"Put your toys away.","opts":["put away","put behind","put out","put along"]},{"q":"'Apagar (fogo/cigarro)':","ans":0,"ctx":"","exp":"Put out the fire.","opts":["put out","put off","put down","put over"]},{"q":"'Transferir a ligação':","ans":0,"ctx":"","exp":"I'll put you through.","opts":["put you through","put you over","put you across","put you along"]}]$j$::jsonb where id = '46874662-5b73-49b4-ae95-f8cd07b5d733';
update licoes set titulo = 'Phrasal verbs com GO II', exemplos = $j$[{"en":"What's going on here?","pt":"O que está acontecendo aqui?"},{"en":"The alarm went off at 5am.","pt":"O alarme disparou às 5 da manhã."},{"en":"Prices went up again this month.","pt":"Os preços subiram de novo este mês."}]$j$::jsonb, questoes = $j$[{"q":"'Continuar':","ans":0,"ctx":"","exp":"Go on = continue.","opts":["go on","go out","go off","go under"]},{"q":"'O alarme disparou':","ans":0,"ctx":"","exp":"Go off.","opts":["went off","went out","went on","went away"]},{"q":"'Sair (à noite)':","ans":0,"ctx":"","exp":"Going out tonight?","opts":["go out","go off","go on","go over"]},{"q":"'O leite estragou':","ans":0,"ctx":"","exp":"Go off = estragar (BrE).","opts":["went off","went down","went out","went over"]},{"q":"'Revisar (o material)':","ans":0,"ctx":"","exp":"Go over the notes.","opts":["go over","go without","go against","go into fast"]},{"q":"'Ficar sem (café)':","ans":0,"ctx":"","exp":"Go without coffee.","opts":["go without","go outside","go off from","go away from"]}]$j$::jsonb where id = '3c7e7e35-21f1-4b5f-bd03-a0e0ed77909d';
update licoes set titulo = 'Phrasal verbs com GIVE II', exemplos = $j$[{"en":"Don't give up on your dreams!","pt":"Não desista dos seus sonhos!"},{"en":"Can you give back my pen?","pt":"Pode devolver minha caneta?"},{"en":"She gave away all her old clothes.","pt":"Ela doou todas as roupas antigas."}]$j$::jsonb, questoes = $j$[{"q":"'Desistir':","ans":0,"ctx":"","exp":"Give up smoking.","opts":["give up","give in only","give out","give away"]},{"q":"'Devolver':","ans":0,"ctx":"","exp":"Give it back!","opts":["give back","give again","give return","give off"]},{"q":"'Ceder (à pressão)':","ans":0,"ctx":"","exp":"He finally gave in.","opts":["give in","give on","give under","give low"]},{"q":"'Doar':","ans":0,"ctx":"","exp":"Give away clothes.","opts":["give away","give far","give without","give from"]},{"q":"'Distribuir (panfletos)':","ans":0,"ctx":"","exp":"Give out flyers.","opts":["give out","give around","give over","give onto"]},{"q":"'Entregar o segredo sem querer':","ans":0,"ctx":"","exp":"Don't give it away!","opts":["give it away","give it back","give it in","give it off"]}]$j$::jsonb where id = '7536347c-721d-493d-954b-c4f6049d8256';
update licoes set titulo = 'Phrasal verbs com HOLD II', exemplos = $j$[{"en":"Hold on a second, please.","pt":"Espere um segundo, por favor."},{"en":"Sorry, I was held up in traffic.","pt":"Desculpe, fiquei preso no trânsito."},{"en":"She couldn't hold back her tears.","pt":"Ela não conseguiu conter as lágrimas."}]$j$::jsonb, questoes = $j$[{"q":"'Espere um pouco':","ans":0,"ctx":"","exp":"Hold on!","opts":["hold on","hold off forever","hold down","hold away"]},{"q":"'Fui atrasado (trânsito)':","ans":0,"ctx":"","exp":"Held up in traffic.","opts":["held up","held on","held out","held over"]},{"q":"'Conter (lágrimas/raiva)':","ans":0,"ctx":"","exp":"Hold back tears.","opts":["hold back","hold behind","hold low","hold inside out"]},{"q":"'Resistir (não ceder)':","ans":0,"ctx":"","exp":"Hold out for more.","opts":["hold out","hold away","hold against","hold from"]},{"q":"'Agarre-se a (não solte)':","ans":0,"ctx":"","exp":"Hold onto the rail.","opts":["hold onto","hold at","hold beside","hold along"]},{"q":"'Hold up' também é:","ans":0,"ctx":"","exp":"A bank hold-up.","opts":["assaltar","elogiar","construir","pintar"]}]$j$::jsonb where id = '8cdc34fa-acec-429b-81fd-1fd4c44579a9';
update licoes set titulo = 'Mixed Conditionals II', exemplos = $j$[{"en":"If I had saved money, I would be rich now.","pt":"Se eu tivesse poupado, seria rico agora."},{"en":"If she were taller, she would have become a model.","pt":"Se ela fosse mais alta, teria virado modelo."},{"en":"If I weren't so tired, I would have gone out.","pt":"Se eu não estivesse tão cansado, teria saído."}]$j$::jsonb, questoes = $j$[{"q":"'If I ___ harder, I would have a better job now.'","ans":0,"ctx":"","exp":"Passado (had studied) + resultado presente (would have).","opts":["had studied","studied","study","would study"]},{"q":"Mixed conditional combina:","ans":0,"ctx":"","exp":"Tempos misturados.","opts":["Tempos diferentes em condição e resultado","Só o presente","Só o passado","Dois futuros"]},{"q":"'If he weren't shy, he ___ asked her out.'","ans":0,"ctx":"","exp":"Estado presente + resultado passado: would have.","opts":["would have","will have","would","had"]},{"q":"'If I had taken that job, I ___ in Paris now.'","ans":0,"ctx":"","exp":"Resultado presente: would be.","opts":["would be","would have been","will be","am"]},{"q":"'If she had slept, she ___ tired now.'","ans":0,"ctx":"","exp":"Presente: wouldn't be.","opts":["wouldn't be","wouldn't have been","won't be","isn't"]},{"q":"O que torna um conditional 'mixed'?","ans":0,"ctx":"","exp":"Tempos distintos.","opts":["Condição e consequência em tempos distintos","Usar will","Não ter if","Ser informal"]}]$j$::jsonb where id = 'b8b8a675-7272-4214-83ac-f605f3b72c96';
update licoes set titulo = 'Inversão para ênfase II', exemplos = $j$[{"en":"Never have I seen such a mess.","pt":"Nunca vi tamanha bagunça."},{"en":"Not only did he lie, but he also cheated.","pt":"Ele não só mentiu, como também trapaceou."},{"en":"Hardly had I arrived when it started.","pt":"Mal cheguei e começou."}]$j$::jsonb, questoes = $j$[{"q":"'Never ___ I seen this.'","ans":0,"ctx":"","exp":"Inversão: Never have I seen.","opts":["have","I have","has","did"]},{"q":"A inversão é usada para:","ans":0,"ctx":"","exp":"Ênfase em registro formal.","opts":["Ênfase formal","Perguntas comuns","Tempo futuro","Informalidade"]},{"q":"'Not only ___ he rich, but also kind.'","ans":0,"ctx":"","exp":"Not only is he...","opts":["is","he is","does","has"]},{"q":"'Rarely ___ we see such talent.'","ans":0,"ctx":"","exp":"Rarely do we see.","opts":["do","we","are","have"]},{"q":"'No sooner ___ he left than she called.'","ans":0,"ctx":"","exp":"No sooner had he left.","opts":["had","did","has","was"]},{"q":"'Hardly ___ I sat down when...'","ans":0,"ctx":"","exp":"Hardly had I sat down.","opts":["had","did","have","was"]}]$j$::jsonb where id = 'ef5802b9-d1ae-42bc-9021-1ceaab09c7c1';
update licoes set titulo = 'Present Perfect Continuous III', exemplos = $j$[{"en":"I've been working all day.","pt":"Tenho trabalhado o dia todo."},{"en":"She's been learning English for years.","pt":"Ela estuda inglês há anos."},{"en":"Why are you tired? I've been running.","pt":"Por que está cansado? Estive correndo."}]$j$::jsonb, questoes = $j$[{"q":"Estrutura do present perfect continuous:","ans":0,"ctx":"","exp":"have been + -ing.","opts":["have/has been + verbo-ing","have + particípio","was + -ing","will be + -ing"]},{"q":"'I've ___ waiting for an hour.'","ans":0,"ctx":"","exp":"have been + -ing.","opts":["been","be","being","was"]},{"q":"Ele enfatiza:","ans":0,"ctx":"","exp":"Duração/atividade.","opts":["a duração da ação","só o resultado","o futuro","uma rotina"]},{"q":"'She ___ studying all morning.'","ans":0,"ctx":"","exp":"She has been.","opts":["has been","have been","is been","was been"]},{"q":"'They've been ___ for hours.'","ans":0,"ctx":"","exp":"+ verbo-ing.","opts":["talking","talk","talked","talks"]},{"q":"Diferença para o present perfect simples:","ans":0,"ctx":"","exp":"Duração vs resultado.","opts":["foca na duração, não só no resultado","é o passado","é o futuro","não há diferença"]}]$j$::jsonb where id = '16fcac66-5984-4add-a955-25e5f0709259';
update licoes set titulo = 'Past Perfect II', exemplos = $j$[{"en":"The film had started when we arrived.","pt":"O filme já tinha começado quando chegamos."},{"en":"She had never seen snow before.","pt":"Ela nunca tinha visto neve antes."},{"en":"I had finished before he called.","pt":"Eu tinha terminado antes de ele ligar."}]$j$::jsonb, questoes = $j$[{"q":"Estrutura do past perfect:","ans":0,"ctx":"","exp":"had + particípio.","opts":["had + particípio","have + particípio","was + -ing","did + verbo"]},{"q":"O past perfect indica:","ans":0,"ctx":"","exp":"O passado do passado.","opts":["uma ação anterior a outra no passado","o presente","o futuro","uma rotina"]},{"q":"'When I arrived, they ___ already left.'","ans":0,"ctx":"","exp":"had left.","opts":["had","have","has","was"]},{"q":"'She ___ never seen the sea before.'","ans":0,"ctx":"","exp":"had seen.","opts":["had","has","have","did"]},{"q":"'had' é igual para:","ans":0,"ctx":"","exp":"had para todos.","opts":["todas as pessoas","só he/she/it","só I","só o plural"]},{"q":"'By 2010, he ___ written three books.'","ans":0,"ctx":"","exp":"had written.","opts":["had","has","have","was"]}]$j$::jsonb where id = 'c1dcfe85-272f-4fa3-8d45-a951597d8304';
update licoes set titulo = 'Past Perfect Continuous II', exemplos = $j$[{"en":"He had been driving for hours when he stopped.","pt":"Ele dirigia há horas quando parou."},{"en":"They had been waiting a long time.","pt":"Eles esperavam havia muito tempo."},{"en":"I was wet because it had been raining.","pt":"Eu estava molhado porque tinha chovido."}]$j$::jsonb, questoes = $j$[{"q":"Estrutura:","ans":0,"ctx":"","exp":"had been + -ing.","opts":["had been + verbo-ing","had + particípio","have been + -ing","was + -ing"]},{"q":"Enfatiza:","ans":0,"ctx":"","exp":"Duração no passado.","opts":["duração antes de um momento no passado","só o resultado","o presente","o futuro"]},{"q":"'She was tired. She ___ working all day.'","ans":0,"ctx":"","exp":"had been working.","opts":["had been","has been","was been","had"]},{"q":"'They ___ waiting for an hour when the bus came.'","ans":0,"ctx":"","exp":"had been waiting.","opts":["had been","have been","were been","had"]},{"q":"'The ground was wet; it ___ raining.'","ans":0,"ctx":"","exp":"had been raining.","opts":["had been","has been","was been","had"]},{"q":"'+ verbo' fica:","ans":0,"ctx":"","exp":"had been + verbo-ing.","opts":["com -ing","com -ed","na base","com to"]}]$j$::jsonb where id = 'e195fb65-98d5-4020-b030-5a503947650b';
update licoes set titulo = 'Third Conditional III', exemplos = $j$[{"en":"If I had known, I would have helped.","pt":"Se eu soubesse, teria ajudado."},{"en":"She would have come if you had invited her.","pt":"Ela teria vindo se você a tivesse convidado."},{"en":"If we had left earlier, we wouldn't have missed it.","pt":"Se tivéssemos saído antes, não teríamos perdido."}]$j$::jsonb, questoes = $j$[{"q":"Estrutura da third conditional:","ans":0,"ctx":"","exp":"Passado irreal.","opts":["If + had + particípio, would have + particípio","If + passado, would","If + presente, will","If + presente, presente"]},{"q":"'If I ___ known, I would have called.'","ans":0,"ctx":"","exp":"had known.","opts":["had","have","did","would have"]},{"q":"'I would ___ helped if you had asked.'","ans":0,"ctx":"","exp":"would have helped.","opts":["have","had","has","be"]},{"q":"A third conditional fala de:","ans":0,"ctx":"","exp":"Passado que não aconteceu.","opts":["passado irreal (arrependimento)","futuro provável","fato geral","hipótese presente"]},{"q":"'If she had studied, she ___ passed.'","ans":0,"ctx":"","exp":"would have passed.","opts":["would have","would","will have","had"]},{"q":"'If they ___ left earlier, they wouldn't have missed it.'","ans":0,"ctx":"","exp":"had left.","opts":["had","have","did","would have"]}]$j$::jsonb where id = 'a3a95bba-e38b-4699-88e6-231d6fdf9c90';
update licoes set titulo = 'Expressões latinas no inglês II', exemplos = $j$[{"en":"The idea isn't bad per se.","pt":"A ideia não é ruim em si."},{"en":"Fruits, e.g. apples and pears.","pt":"Frutas, por exemplo maçãs e peras."},{"en":"He helps her and vice versa.","pt":"Ele a ajuda e vice-versa."}]$j$::jsonb, questoes = $j$[{"q":"'per se' =","ans":0,"ctx":"","exp":"em si.","opts":["em si mesmo","por favor","perto","depois"]},{"q":"'e.g.' =","ans":0,"ctx":"","exp":"por exemplo.","opts":["por exemplo","isto é","etc.","ou seja"]},{"q":"'i.e.' =","ans":0,"ctx":"","exp":"isto é.","opts":["isto é/ou seja","por exemplo","e assim por diante","versus"]},{"q":"'vice versa' =","ans":0,"ctx":"","exp":"o inverso.","opts":["o contrário também","de novo","por acaso","ao vivo"]},{"q":"'status quo' =","ans":0,"ctx":"","exp":"situação atual.","opts":["situação atual","status alto","estatística","parada"]},{"q":"'ad hoc' =","ans":0,"ctx":"","exp":"para um fim específico.","opts":["feito para um fim específico","antigo","adicional só","aleatório"]}]$j$::jsonb where id = '80c6a1d0-6c31-4f7c-a08f-ce2fbc6fc042';
update licoes set titulo = 'Idioms com comida II', exemplos = $j$[{"en":"The test was a piece of cake.","pt":"A prova foi moleza."},{"en":"Who spilled the beans about the party?","pt":"Quem entregou o segredo da festa?"},{"en":"In a nutshell, we need more time.","pt":"Em resumo, precisamos de mais tempo."}]$j$::jsonb, questoes = $j$[{"q":"'Piece of cake' =","ans":0,"ctx":"","exp":"Moleza.","opts":["muito fácil","sobremesa","pedaço pequeno","receita"]},{"q":"'Spill the beans' =","ans":0,"ctx":"","exp":"Entregar o segredo.","opts":["revelar um segredo","derrubar comida","cozinhar mal","fazer bagunça"]},{"q":"'Butter someone up' =","ans":0,"ctx":"","exp":"Elogiar por interesse.","opts":["bajular","engordar","cozinhar para alguém","irritar"]},{"q":"'In a nutshell' =","ans":0,"ctx":"","exp":"Resumidamente.","opts":["em resumo","dentro da casca","em segredo","com detalhes"]},{"q":"'Bring home the bacon' =","ans":0,"ctx":"","exp":"Ganhar o pão.","opts":["sustentar a casa","fazer compras","cozinhar bacon","chegar cedo"]},{"q":"A melhor tradução de 'moleza' é:","ans":0,"ctx":"","exp":"Idiom clássico.","opts":["a piece of cake","a slice of bread","a cup of tea only","a bowl of soup"]}]$j$::jsonb where id = '4d2a0639-d44c-4828-98fb-305cea92e34d';
update licoes set titulo = 'Idioms com cores II', exemplos = $j$[{"en":"He called me out of the blue.","pt":"Ele me ligou do nada."},{"en":"We eat out once in a blue moon.","pt":"Comemos fora raramente."},{"en":"It was just a white lie.","pt":"Foi só uma mentirinha."}]$j$::jsonb, questoes = $j$[{"q":"'Out of the blue' =","ans":0,"ctx":"","exp":"Do nada.","opts":["de repente, sem aviso","do fundo do mar","de tristeza","com calma"]},{"q":"'Once in a blue moon' =","ans":0,"ctx":"","exp":"Quase nunca.","opts":["muito raramente","toda lua cheia","uma vez por mês","sempre à noite"]},{"q":"'Green with envy' =","ans":0,"ctx":"","exp":"Inveja intensa.","opts":["morto de inveja","passando mal","sem experiência","ecológico"]},{"q":"'Red tape' =","ans":0,"ctx":"","exp":"Excesso de burocracia.","opts":["burocracia","fita adesiva","perigo","multa"]},{"q":"'White lie' =","ans":0,"ctx":"","exp":"Mentirinha social.","opts":["mentira inofensiva","mentira grave","verdade dura","segredo"]},{"q":"'Caught red-handed' =","ans":0,"ctx":"","exp":"Flagrante.","opts":["pego no flagra","com frio","machucado","envergonhado"]}]$j$::jsonb where id = 'dcb058f6-aae8-40ce-847f-db1c14235639';
update licoes set titulo = 'Idioms com números II', exemplos = $j$[{"en":"The deal failed, so we're back to square one.","pt":"O acordo falhou, voltamos à estaca zero."},{"en":"She's been on cloud nine since the news.","pt":"Ela está nas nuvens desde a notícia."},{"en":"Don't trust him — he's two-faced.","pt":"Não confie nele — ele é falso."}]$j$::jsonb, questoes = $j$[{"q":"'Back to square one' =","ans":0,"ctx":"","exp":"Recomeçar do zero.","opts":["voltar à estaca zero","voltar para casa","ganhar o jogo","ficar em 1º"]},{"q":"'On cloud nine' =","ans":0,"ctx":"","exp":"Nas nuvens.","opts":["muito feliz","no avião","distraído","com medo"]},{"q":"'Two-faced' =","ans":0,"ctx":"","exp":"Tem duas caras.","opts":["falso, hipócrita","gêmeo","indeciso","duas vezes melhor"]},{"q":"'At sixes and sevens' =","ans":0,"ctx":"","exp":"Bagunça e confusão.","opts":["confuso, desorganizado","jogando dados","bem arrumado","atrasado"]},{"q":"'It takes two to tango' =","ans":0,"ctx":"","exp":"Os dois lados participam.","opts":["a culpa é dos dois","dançar é bom","é preciso treinar","vá dançar"]},{"q":"'The eleventh hour' =","ans":0,"ctx":"","exp":"Em cima da hora.","opts":["o último momento","onze da manhã","hora do almoço","hora extra"]}]$j$::jsonb where id = 'ec9eb5e6-ac1d-4427-b117-15b77d3f0297';

