delete from licoes where id in ('2ac2f873-a801-4204-a934-c0a96185bb30', '7065bdf7-cee2-497b-bbf3-8a379fe7caa7', '2a2a39f4-3ffb-421d-b95d-d95e199fbe50', '7de6ad8d-6425-4cd6-b980-ffa996532a1a', 'e73516b8-e576-4f64-aa57-251af6edb7f5', 'a9e5861f-e3c2-414c-9ab6-ef5747d5a4c6', '049cb3b9-fb37-4f8d-b280-e2e502b5fe5b');

-- 3/3: atualiza progresso dos alunos (lição concluída é rastreada por TÍTULO)
do $do$
declare tipo text;
begin
  select data_type into tipo from information_schema.columns
    where table_schema = 'public' and table_name = 'progresso' and column_name = 'licoes_concluidas';
  if tipo = 'jsonb' then
    update progresso p set licoes_concluidas = coalesce((
      select jsonb_agg(to_jsonb(coalesce(m.novo, x.t)))
      from jsonb_array_elements_text(p.licoes_concluidas) as x(t)
      left join (values
        ('Phrasal verbs separaveis', 'Phrasal verbs separáveis II'),
        ('Inversao para enfase', 'Inversão para ênfase III'),
        ('Cleft sentences', 'Cleft sentences II'),
        ('Mixed conditionals', 'Mixed conditionals III'),
        ('Gerundio x infinitivo (sentido)', 'Gerúndio x infinitivo (sentido)'),
        ('Modais de deducao no passado', 'Modais de dedução no passado'),
        ('Colocacoes com TAKE', 'Colocações com TAKE'),
        ('Verbo + preposicao', 'Verbo + preposição'),
        ('Enfase com so / such', 'Ênfase com so / such'),
        ('Substantivos incontaveis', 'Substantivos incontáveis'),
        ('Formacao de palavras: sufixos', 'Formação de palavras: sufixos II'),
        ('Suavizar opinioes (hedging)', 'Suavizar opiniões (hedging)'),
        ('Idioms com partes do corpo', 'Idioms com partes do corpo II'),
        ('Idioms com animais', 'Idioms com animais II'),
        ('Sinonimos de BIG', 'Sinônimos de BIG'),
        ('Sinonimos de ANGRY', 'Sinônimos de ANGRY'),
        ('Conotacao', 'Conotação'),
        ('Phrasal verbs de negocios', 'Phrasal verbs de negócios'),
        ('Fronting para enfase', 'Fronting para ênfase'),
        ('Subjuntivo em ingles', 'Subjuntivo em inglês II'),
        ('Inversao avancada', 'Inversão avançada'),
        ('Enfase: the very / the only', 'Ênfase: the very / the only'),
        ('Nominalizacao (academico)', 'Nominalização (acadêmico)'),
        ('Comparacoes idiomaticas', 'Comparações idiomáticas'),
        ('Ironia e sarcasmo', 'Ironia e sarcasmo II'),
        ('Understatement e hiperbole', 'Understatement e hipérbole'),
        ('Metafora no dia a dia', 'Metáfora no dia a dia'),
        ('Abreviacoes latinas', 'Abreviações latinas'),
        ('Contracoes coloquiais', 'Contrações coloquiais'),
        ('Proverbios', 'Provérbios'),
        ('Giria x padrao (registro)', 'Gíria x padrão (registro)'),
        ('Make x Do (avancado)', 'Make x Do (avançado)'),
        ('Wish / If only', 'Wish / If only II'),
        ('Reported speech avancado', 'Reported speech avançado II'),
        ('Adjetivo + preposicao', 'Adjetivo + preposição III'),
        ('Artigos avancados', 'Artigos avançados'),
        ('Sinonimos de HAPPY', 'Sinônimos de HAPPY'),
        ('Homofonos que confundem', 'Homófonos que confundem')
      ) as m(velho, novo) on m.velho = x.t
    ), '[]'::jsonb)
    where p.licoes_concluidas is not null and jsonb_typeof(p.licoes_concluidas) = 'array';
  elsif tipo = 'ARRAY' then
    update progresso p set licoes_concluidas = coalesce((
      select array_agg(coalesce(m.novo, x.t))
      from unnest(p.licoes_concluidas) as x(t)
      left join (values
        ('Phrasal verbs separaveis', 'Phrasal verbs separáveis II'),
        ('Inversao para enfase', 'Inversão para ênfase III'),
        ('Cleft sentences', 'Cleft sentences II'),
        ('Mixed conditionals', 'Mixed conditionals III'),
        ('Gerundio x infinitivo (sentido)', 'Gerúndio x infinitivo (sentido)'),
        ('Modais de deducao no passado', 'Modais de dedução no passado'),
        ('Colocacoes com TAKE', 'Colocações com TAKE'),
        ('Verbo + preposicao', 'Verbo + preposição'),
        ('Enfase com so / such', 'Ênfase com so / such'),
        ('Substantivos incontaveis', 'Substantivos incontáveis'),
        ('Formacao de palavras: sufixos', 'Formação de palavras: sufixos II'),
        ('Suavizar opinioes (hedging)', 'Suavizar opiniões (hedging)'),
        ('Idioms com partes do corpo', 'Idioms com partes do corpo II'),
        ('Idioms com animais', 'Idioms com animais II'),
        ('Sinonimos de BIG', 'Sinônimos de BIG'),
        ('Sinonimos de ANGRY', 'Sinônimos de ANGRY'),
        ('Conotacao', 'Conotação'),
        ('Phrasal verbs de negocios', 'Phrasal verbs de negócios'),
        ('Fronting para enfase', 'Fronting para ênfase'),
        ('Subjuntivo em ingles', 'Subjuntivo em inglês II'),
        ('Inversao avancada', 'Inversão avançada'),
        ('Enfase: the very / the only', 'Ênfase: the very / the only'),
        ('Nominalizacao (academico)', 'Nominalização (acadêmico)'),
        ('Comparacoes idiomaticas', 'Comparações idiomáticas'),
        ('Ironia e sarcasmo', 'Ironia e sarcasmo II'),
        ('Understatement e hiperbole', 'Understatement e hipérbole'),
        ('Metafora no dia a dia', 'Metáfora no dia a dia'),
        ('Abreviacoes latinas', 'Abreviações latinas'),
        ('Contracoes coloquiais', 'Contrações coloquiais'),
        ('Proverbios', 'Provérbios'),
        ('Giria x padrao (registro)', 'Gíria x padrão (registro)'),
        ('Make x Do (avancado)', 'Make x Do (avançado)'),
        ('Wish / If only', 'Wish / If only II'),
        ('Reported speech avancado', 'Reported speech avançado II'),
        ('Adjetivo + preposicao', 'Adjetivo + preposição III'),
        ('Artigos avancados', 'Artigos avançados'),
        ('Sinonimos de HAPPY', 'Sinônimos de HAPPY'),
        ('Homofonos que confundem', 'Homófonos que confundem')
      ) as m(velho, novo) on m.velho = x.t
    ), '{}')
    where p.licoes_concluidas is not null;
  end if;
end $do$;

commit;
